using Microsoft.EntityFrameworkCore;

namespace DotnetDojo.Api.V3DB01_QueryShapes;

public class Ex1 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapGet("/v3db01/books", ListBooks);
    }

    private static async Task<IResult> ListBooks(string city, V3Db01Db db)
    {
        // One command. The filter, the sort and the aggregate all run in the
        // database, and BookRow is not an entity type so nothing is tracked.
        var rows = await db.Books
            .Where(b => b.Branch.City == city)
            .OrderBy(b => b.Title)
            .Select(b => new BookRow(b.Id, b.Title, b.Author, b.Copies.Count()))
            .ToListAsync();

        return TypedResults.Ok(rows);
    }
}

