// v3db01_query_shapes / ex2 - reference solution (author only, used by `dojo verify`).

using Microsoft.EntityFrameworkCore;

namespace DotnetDojo.Api.V3DB01_QueryShapes;

public class Ex2 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapGet("/v3db01/search", Search);
    }

    private static async Task<IResult> Search(string? term, V3Db01Db db)
    {
        string trimmed = (term ?? string.Empty).Trim();
        if (trimmed.Length < 2)
        {
            return TypedResults.BadRequest("term must be at least two characters.");
        }

        // LIKE '%term%' - translatable, and the pattern is written where a
        // reader can see it. Case folding is the collation's job, not ours:
        // wrapping the column in LOWER() would make any index unusable.
        var rows = await db.Books
            .Where(b => EF.Functions.Like(b.Title, $"%{trimmed}%"))
            .OrderBy(b => b.Title)
            .Select(b => new BookRow(b.Id, b.Title, b.Author, b.Copies.Count()))
            .ToListAsync();

        return TypedResults.Ok(rows);
    }
}

