using Microsoft.EntityFrameworkCore;

namespace DotnetDojo.Api.V3DB01_QueryShapes;

public class Ex3 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapGet("/v3db01/branches/{id:int}/shelf", Shelf);
    }

    private static async Task<IResult> Shelf(int id, V3Db01Db db)
    {
        // Command one: the name doubles as the existence check.
        string? branch = await db.Branches
            .Where(b => b.Id == id)
            .Select(b => b.Name)
            .FirstOrDefaultAsync();
        if (branch is null)
        {
            return TypedResults.NotFound();
        }

        // Command two: both aggregates as correlated subqueries. No loop, no
        // navigation touched in C#, and no Book ever constructed.
        var books = await db.Books
            .Where(b => b.BranchId == id)
            .OrderBy(b => b.Title)
            .Select(b => new ShelfRow(
                b.Title,
                b.Copies.Count(),
                b.Copies.SelectMany(c => c.Loans).Count(l => l.ReturnedAt == null)))
            .ToListAsync();

        return TypedResults.Ok(new ShelfReport(branch, books));
    }
}

