public class Ex4 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapGet("/v3db01/books/{id:int}/detail", Detail);
    }

    private static async Task<IResult> Detail(int id, V3Db01Db db)
    {
        // Each collection becomes its own correlated sub-select, so the
        // database never produces copies x reviews rows. The 404 falls out of
        // the same command.
        var detail = await db.Books
            .Where(b => b.Id == id)
            .Select(b => new BookDetail(
                b.Title,
                b.Copies.OrderBy(c => c.Barcode).Select(c => c.Barcode).ToList(),
