                    .OrderByDescending(r => r.PostedAt)
                    .Select(r => new ReviewRow(r.Stars, r.Body))
                    .ToList()))
            .FirstOrDefaultAsync();

        return detail is null ? TypedResults.NotFound() : TypedResults.Ok(detail);
    }
