using Microsoft.EntityFrameworkCore;

namespace DotnetDojo.Api.V3DB01_QueryShapes;

public class Ex5 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapGet("/v3db01/catalogue", Catalogue);
    }

    private static async Task<IResult> Catalogue(V3Db01Db db)
    {
        // Identity resolution without tracking: EF keeps a private identity
        // map for the lifetime of this one query, so the eight books share
        // two Branch instances, and discards it afterwards. The change
        // tracker stays empty.
        var books = await db.Books
            .Include(b => b.Branch)
            .AsNoTrackingWithIdentityResolution()
            .OrderBy(b => b.Title)
            .ToListAsync();

        int instances = V3Db01Graph.CountBranches(books);
        var rows = books.Select(b => new CatalogueRow(b.Title, b.Branch.Name)).ToList();

        return TypedResults.Ok(new CatalogueReport(instances, rows));
    }
}

