using Microsoft.EntityFrameworkCore;

namespace DotnetDojo.Api.V3DB01_QueryShapes;

public class Ex6 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapGet("/v3db01/members/{id:int}/current", Current);
    }

    private static async Task<IResult> Current(int id, V3Db01Db db)
    {
        // The filter and the ordering live inside the projected collection, so
        // the database returns the two open loans, not four hundred and two.
        // FirstOrDefaultAsync distinguishes "no such member" (null) from
        // "member with nothing on loan" (an object with an empty list).
        var result = await db.Members
            .Where(m => m.Id == id)
            .Select(m => new MemberLoans(
                m.Name,
                m.Loans
                    .Where(l => l.ReturnedAt == null)
                    .OrderByDescending(l => l.TakenAt)
                    .Select(l => new LoanRow(l.Id, l.Copy.Barcode, l.Copy.Book.Title, l.TakenAt))
                    .ToList()))
            .FirstOrDefaultAsync();

        return result is null ? TypedResults.NotFound() : TypedResults.Ok(result);
    }
}

