using Microsoft.EntityFrameworkCore;

namespace DotnetDojo.Api.V3DB01_QueryShapes;

public class Ex7 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapPost("/v3db01/authors/{author}/withdraw", Withdraw);
    }

    private static async Task<IResult> Withdraw(string author, V3Db01Db db)
    {
        // The global filter (Withdrawn == false) is part of this WHERE, so the
        // update only touches rows that are not already withdrawn and the row
        // count is both the answer and the existence check.
        int changed = await db.Books
            .Where(b => b.Author == author)
            .ExecuteUpdateAsync(s => s.SetProperty(b => b.Withdrawn, true));
        if (changed == 0)
        {
            return TypedResults.NotFound();
        }

        // The same filter would make this count zero forever, so suppress it.
        int total = await db.Books
            .IgnoreQueryFilters()
            .CountAsync(b => b.Author == author && b.Withdrawn);

        return TypedResults.Ok(new WithdrawReport(changed, total));
    }
}

