// v3db01_query_shapes / ex8 - reference solution (author only, used by `dojo verify`).

using Microsoft.EntityFrameworkCore;

namespace DotnetDojo.Api.V3DB01_QueryShapes;

public class Ex8 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapGet("/v3db01/loans", Page);
    }

    private static async Task<IResult> Page(int size, string? after, V3Db01Db db)
    {
        if (size < 1 || size > 50)
        {
            return TypedResults.BadRequest("size must be between 1 and 50.");
        }

        DateTime cursorTaken = default;
        int cursorId = 0;
        bool hasCursor = false;
        if (!string.IsNullOrEmpty(after))
        {
            if (!V3Db01Cursor.TryParse(after, out cursorTaken, out cursorId))
            {
                return TypedResults.BadRequest("after is not a valid cursor.");
            }
            hasCursor = true;
        }

        IQueryable<Loan> query = db.Loans;
        if (hasCursor)
        {
            // Total order over (TakenAt desc, Id desc): strictly earlier, or
            // the same instant with a strictly smaller key. An index seek at
            // page 1 and at page 900 alike - no OFFSET anywhere.
            query = query.Where(l =>
                l.TakenAt < cursorTaken || (l.TakenAt == cursorTaken && l.Id < cursorId));
        }

        // One extra row is the "is there another page" probe.
        var rows = await query
            .OrderByDescending(l => l.TakenAt)
            .ThenByDescending(l => l.Id)
            .Take(size + 1)
            .Select(l => new LoanRow(l.Id, l.Copy.Barcode, l.Copy.Book.Title, l.TakenAt))
            .ToListAsync();

        bool more = rows.Count > size;
        if (more)
        {
            rows.RemoveAt(rows.Count - 1);
        }

        string? next = more && rows.Count > 0 ? V3Db01Cursor.Format(rows[^1]) : null;
        return TypedResults.Ok(new LoanPage(rows, next));
    }
}

