using Microsoft.EntityFrameworkCore;

namespace DotnetDojo.Api.V3DB01_QueryShapes;

public class Challenge : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapGet("/v3db01/report", Report);
    }

    private static async Task<IResult> Report(V3Db01Db db)
    {
        // One command. The intermediate projection lets the outer ordering
        // reference OpenLoans without repeating the subquery, and because it
        // is still an IQueryable the sort happens in SQL, not in memory.
        var rows = await db.Branches
            .TagWith("v3db01-report")
            .Select(b => new BranchReport(
                b.Name,
                b.Books
                    .SelectMany(x => x.Copies)
                    .SelectMany(c => c.Loans)
                    .Count(l => l.ReturnedAt == null),
                b.Books
                    .OrderByDescending(x => x.Copies.SelectMany(c => c.Loans).Count())
                    .ThenBy(x => x.Title)
                    .Take(3)
                    .Select(x => x.Title)
                    .ToList()))
            .OrderByDescending(r => r.OpenLoans)
            .ThenBy(r => r.Name)
            .ToListAsync();

        return TypedResults.Ok(rows);
    }
}

