using Microsoft.EntityFrameworkCore;

namespace DotnetDojo.Api.V3DB01_QueryShapes;

public class Review1 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapGet("/v3db01/books/{id:int}/availability", Availability);
    }

    private static async Task<IResult> Availability(int id, V3Db01Db db)
    {
        // IgnoreQueryFilters is what makes "withdrawn" distinguishable from
        // "absent": with the filter on, both come back as null. One command
        // carries all three outcomes.
        var row = await db.Books
            .IgnoreQueryFilters()
            .Where(b => b.Id == id)
            .Select(b => new
            {
                b.Title,
                b.Withdrawn,
                HasFreeCopy = b.Copies.Any(c => !c.Loans.Any(l => l.ReturnedAt == null)),
                OpenLoans = b.Copies.SelectMany(c => c.Loans).Count(l => l.ReturnedAt == null),
            })
            .FirstOrDefaultAsync();

        if (row is null)
        {
            return TypedResults.NotFound();
        }
        if (row.Withdrawn)
        {
            return TypedResults.StatusCode(StatusCodes.Status410Gone);
        }

        return TypedResults.Ok(new Availability(row.Title, row.HasFreeCopy, row.OpenLoans));
    }
}

