// v3db02_mapping_conversions / ex2 - reference solution (author only, used by `dojo verify`).

using Microsoft.EntityFrameworkCore;

namespace DotnetDojo.Api.V3DB02_MappingConversions;

public static class Ex2Model
{
    public static void Configure(ModelBuilder builder)
    {
        builder.Entity<Customer>(e =>
        {
            e.ToTable("customers");
            e.Property(c => c.Name).HasColumnName("name").IsRequired();
            e.Property(c => c.Id).HasColumnName("id");

            // Table splitting: no join, no second table, no navigation back.
            e.OwnsOne(c => c.Billing, a =>
            {
                a.Property(x => x.Line1).HasColumnName("billing_line1").IsRequired();
                a.Property(x => x.City).HasColumnName("billing_city").IsRequired();
                a.Property(x => x.Postcode).HasColumnName("billing_postcode").IsRequired();
            });
        });
    }
}

public class Ex2 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapPost("/v3db02/customers", Create);
        app.MapGet("/v3db02/customers/{id:int}", Get);
        app.MapGet("/v3db02/model/customer", Columns);
    }

    private static async Task<IResult> Create(CustomerRequest request, Ex2Db db)
    {
        var customer = new Customer
        {
            Name = request.Name,
            Billing = new Address(request.Line1, request.City, request.Postcode),
        };
        db.Customers.Add(customer);
        await db.SaveChangesAsync();

        return TypedResults.Created($"/v3db02/customers/{customer.Id}", new { id = customer.Id });
    }

    private static async Task<IResult> Get(int id, Ex2Db db)
    {
        // No Include: an owned reference always travels with its owner.
        var customer = await db.Customers.FirstOrDefaultAsync(c => c.Id == id);
        if (customer is null)
        {
            return TypedResults.NotFound();
        }

        return TypedResults.Ok(new CustomerView(
            customer.Id,
            customer.Name,
            new AddressView(
                customer.Billing.Line1,
                customer.Billing.City,
                customer.Billing.Postcode)));
    }

    private static IResult Columns(Ex2Db db)
    {
        var entity = db.Model.FindEntityType(typeof(Customer))!;
        var table = StoreObjectIdentifier.Table(entity.GetTableName()!, entity.GetSchema());

        var names = entity.GetDeclaredProperties()
            .Concat(entity.GetNavigations()
                .Where(n => n.TargetEntityType.IsOwned())
                .SelectMany(n => n.TargetEntityType.GetDeclaredProperties()))
            .Select(p => p.GetColumnName(table))
            .Where(n => n is not null)
            .Select(n => n!)
            .Distinct()
            .OrderBy(n => n, StringComparer.Ordinal)
            .ToList();

        return TypedResults.Ok(names);
    }
}

