using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.Storage.ValueConversion;

namespace DotnetDojo.Api.V3DB02_MappingConversions;

public static class Ex5Model
{
    public static void Configure(ModelBuilder builder)
    {
        var converter = new ValueConverter<List<string>, string>(
            v => V3Db02Json.Serialise(v),
            v => V3Db02Json.Deserialise(v));

        // The third expression is the fix: without a real copy in the
        // snapshot, EF compares the mutated list with itself and writes
        // nothing. Equality and hash must agree with each other.
        var comparer = new ValueComparer<List<string>>(
            (a, b) => a!.SequenceEqual(b!),
            v => v.Aggregate(0, (hash, item) => HashCode.Combine(hash, item.GetHashCode())),
            v => v.ToList());

        builder.Entity<Invoice>(e =>
        {
            e.ToTable("invoices");
            e.Property(i => i.Tags)
                .HasColumnName("tags")
                .HasConversion(converter, comparer);
        });
    }
}

public class Ex5 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapPost("/v3db02/invoices/{id:int}/tags", AddTag);
    }

    private static async Task<IResult> AddTag(int id, TagRequest request, Ex5Db db)
    {
        var invoice = await db.Invoices.FirstOrDefaultAsync(i => i.Id == id);
        if (invoice is null)
        {
            return TypedResults.NotFound();
        }

        if (invoice.Tags.Contains(request.Tag, StringComparer.OrdinalIgnoreCase))
        {
            return TypedResults.Conflict("tag already present.");
        }

        invoice.Tags.Add(request.Tag);
        await db.SaveChangesAsync();

        return TypedResults.Ok(invoice.Tags.OrderBy(t => t, StringComparer.Ordinal).ToList());
    }
}

