    // decision, so it is written down rather than implied.
    private static readonly ValueConverter<DateTime, DateTime> Utc =
        new(v => v.Kind == DateTimeKind.Utc ? v : v.ToUniversalTime(),
            v => DateTime.SpecifyKind(v, DateTimeKind.Utc));

    public static void Configure(ModelBuilder builder)
    {
        builder.Entity<Payment>(e =>
        {
            e.ToTable("payments");
            e.Property(p => p.Status).HasColumnName("status").HasConversion<string>();
            e.Property(p => p.SettledAt).HasColumnName("settled_at").HasConversion(Utc);
