    private static async Task<IResult> Create(OrderRequest request, ChallengeDb db)
    {
        if (request.Lines.Count == 0 || request.Lines.Any(l => l.Qty <= 0))
        {
            return TypedResults.BadRequest("an order needs at least one line, all with positive quantities.");
        }

        // Client-generated key: the whole aggregate, foreign keys included, is
        // complete before it reaches the database.
        var order = new Order
        {
