            Status = OrderStatus.Placed,
            Total = new Money(request.Lines.Sum(l => l.Amount * l.Qty), request.Currency),
        };

        int lineNo = 1;
        foreach (var line in request.Lines)
        {
            order.Lines.Add(new OrderLine
            {
                LineNo = lineNo++,
                Sku = line.Sku,
                Qty = line.Qty,
                Amount = new Money(line.Amount, request.Currency),
