using Microsoft.EntityFrameworkCore;

namespace DotnetDojo.Api.V3DB03_MigrationsSchema;

public class Ex1 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapGet("/v3db03/schema/status", Status);
    }

    private static async Task<IResult> Status(V3Db03Db db)
    {
        try
        {
            if (!await db.Database.CanConnectAsync())
            {
                return Unavailable();
            }

            // Migration ids carry a timestamp prefix, so the natural order is
            // chronological - no sorting needed.
            var applied = (await db.Database.GetAppliedMigrationsAsync()).ToList();
            var pending = (await db.Database.GetPendingMigrationsAsync()).ToList();

            return TypedResults.Ok(new SchemaStatus(true, applied, pending, pending.Count == 0));
        }
        catch (Exception)
        {
            // A status endpoint that throws is worse than no status endpoint:
            // the one time it is read is the one time nothing else works.
            return Unavailable();
        }
    }

    private static IResult Unavailable() =>
        TypedResults.Json(
            new SchemaStatus(false, [], [], false),
            statusCode: StatusCodes.Status503ServiceUnavailable);
}

