using Microsoft.EntityFrameworkCore;

namespace DotnetDojo.Api.V3DB03_MigrationsSchema;

public class Ex2 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapPost("/v3db03/schema/migrate", Migrate);
    }

    private static async Task<IResult> Migrate(V3Db03Db db)
    {
        // await using: the lease is released even if MigrateAsync throws, so a
        // failed deploy does not leave the lock held by a dead process.
        await using var lease = await V3Db03Lock.AcquireAsync(db, "migrate", TimeSpan.FromSeconds(1));
        if (lease is null)
        {
            // Another replica is doing it. From the deployment's point of view
            // that is success, so 200 rather than 409.
            return TypedResults.Ok(new MigrateReport([], true));
        }

        // Authoritative read happens inside the lock: the answer can change
        // while you are waiting for it.
        var pending = (await db.Database.GetPendingMigrationsAsync()).ToList();
        if (pending.Count > 0)
        {
            await db.Database.MigrateAsync();
        }

        return TypedResults.Ok(new MigrateReport(pending, false));
    }
}

