using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Infrastructure;
using Microsoft.EntityFrameworkCore.Migrations;

namespace DotnetDojo.Api.V3DB03_MigrationsSchema;

public class Ex3 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapGet("/v3db03/schema/script", Script);
    }

    private static IResult Script(string? from, string? to, V3Db03Db db)
    {
        var known = db.Database.GetMigrations().ToList();

        if (from is not null && from != Migration.InitialDatabase && !known.Contains(from))
        {
            return TypedResults.BadRequest(new { error = $"unknown migration: {from}" });
        }
        if (to is not null && !known.Contains(to))
        {
            return TypedResults.BadRequest(new { error = $"unknown migration: {to}" });
        }

        string fromId = from ?? Migration.InitialDatabase;
        string toId = to ?? known[^1];

        // Pure generation: no connection is opened, nothing is applied.
        var migrator = db.Database.GetService<IMigrator>();
        string sql = migrator.GenerateScript(
            fromMigration: fromId,
            toMigration: toId,
            options: MigrationsSqlGenerationOptions.Idempotent);

        return TypedResults.Ok(new ScriptReport(sql, true, fromId, toId));
    }
}

