namespace DotnetDojo.Api.V3DB03_MigrationsSchema;

public class Ex4 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapPost("/v3db03/backfill", Backfill);
    }

    private static async Task<IResult> Backfill(int? batch, V3Db03Db db)
    {
        int size = batch ?? 500;
        if (size < 1 || size > 5000)
        {
            return TypedResults.BadRequest("batch must be between 1 and 5000.");
        }

        // Predicated on the condition it repairs, so it is idempotent: a row
        // already fixed is never selected again, and two concurrent callers
        // cannot both update the same row.
        int updated = await db.Shipments
            .Where(s => s.DispatchedAt == null)
            .Take(size)
            .ExecuteUpdateAsync(setters => setters.SetProperty(
                s => s.DispatchedAt,
                s => s.CreatedAt.AddDays(s.Carrier.LeadTimeDays)));

        int remaining = await db.Shipments.CountAsync(s => s.DispatchedAt == null);

        return TypedResults.Ok(new BackfillReport(updated, remaining, remaining == 0));
    }
}

