    }

    private static async Task<IResult> Contract(V3Db03Db db)
    {
        // db.Model says "required" already - it has since the entity changed.
        // Only the database knows whether the constraint exists.
        bool nullable = await V3Db03Schema.IsColumnNullableAsync(db, "shipments", "dispatched_at");
        if (!nullable)
        {
            return TypedResults.Ok(new ContractReport(false, 0));
        }

