                statusCode: StatusCodes.Status409Conflict);
        }

        await db.Database.ExecuteSqlRawAsync(
            V3Db03Schema.MakeNotNullSql("shipments", "dispatched_at"));

        return TypedResults.Ok(new ContractReport(true, 0));
    }
