// v3db03_migrations_schema / ex6 - reference solution (author only, used by `dojo verify`).

using Microsoft.EntityFrameworkCore;

namespace DotnetDojo.Api.V3DB03_MigrationsSchema;

public class Ex6 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapPost("/v3db03/seed", Seed);
    }

    private static async Task<IResult> Seed(V3Db03Db db)
    {
        await using var tx = await db.Database.BeginTransactionAsync();

        // Natural key, not Id: ids differ between environments because they
        // were assigned by whichever database ran this first.
        var existing = await db.Carriers.ToDictionaryAsync(c => c.Code);

        int inserted = 0, updated = 0, unchanged = 0;
        foreach (var seed in V3Db03Seed.Carriers)
        {
            if (!existing.TryGetValue(seed.Code, out var carrier))
            {
                db.Carriers.Add(new Carrier
                {
                    Code = seed.Code,
                    Name = seed.Name,
                    LeadTimeDays = seed.LeadTimeDays,
                });
                inserted++;
            }
            else if (carrier.Name != seed.Name || carrier.LeadTimeDays != seed.LeadTimeDays)
            {
                carrier.Name = seed.Name;
                carrier.LeadTimeDays = seed.LeadTimeDays;
                updated++;
            }
            else
            {
                unchanged++;
            }
        }

        // Nothing is ever deleted: a row absent from the seed list may have
        // been added deliberately by an operator.
        await db.SaveChangesAsync();
        await tx.CommitAsync();

        return TypedResults.Ok(new SeedReport(inserted, updated, unchanged));
    }
}

