        // source = where the last migration left the schema.
        // target = where the model wants to be. Reversing these produces the
        // operations that would undo your change, which looks plausible.
        var source = V3Db03Schema.LastSnapshotModel(db);
        var target = db.GetService<IDesignTimeModel>().Model.GetRelationalModel();

        var operations = differ.GetDifferences(source, target).ToList();
        var summary = operations.Select(V3Db03Schema.DescribeOperation).ToList();

        return TypedResults.Ok(new DriftReport(operations.Count > 0, operations.Count, summary));
    }
}

