using System.Diagnostics;
using Microsoft.EntityFrameworkCore;

namespace DotnetDojo.Api.V3DB03_MigrationsSchema;

public class Challenge : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapPost("/v3db03/deploy", Deploy);
    }

    private static async Task<IResult> Deploy(V3Db03Db db, IServiceScopeFactory scopes)
    {
        await using var lease = await V3Db03Lock.AcquireAsync(db, "deploy", TimeSpan.FromSeconds(1));
        if (lease is null)
        {
            return TypedResults.Json(
                new DeployReport("busy", [], 0, null, null),
                statusCode: StatusCodes.Status409Conflict);
        }

        // Inside the lock and before migrating: afterwards the list is empty
        // and there is nothing left to report or audit.
        var pending = (await db.Database.GetPendingMigrationsAsync()).ToList();
        if (pending.Count == 0)
        {
            // No audit row: a pipeline that polls this endpoint would fill the
            // table with "nothing happened" within a week.
            return TypedResults.Ok(new DeployReport("up-to-date", [], 0, null, null));
        }

        var sw = Stopwatch.StartNew();
        try
        {
            await db.Database.MigrateAsync();
            sw.Stop();

            int auditId = await V3Db03Audit.WriteAsync(scopes, pending, (int)sw.ElapsedMilliseconds, null);
            return TypedResults.Ok(new DeployReport("applied", pending, (int)sw.ElapsedMilliseconds, null, auditId));
        }
        catch (Exception ex)
        {
            sw.Stop();

            // A separate scope and connection: on a provider with
            // transactional DDL, an audit row enlisted in the migration's own
            // transaction is rolled back along with it.
