using Microsoft.EntityFrameworkCore;

namespace DotnetDojo.Api.V3DB04_TransactionsConcurrency;

public class Ex1 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapPost("/v3db04/transfers", Transfer);
    }

    private static async Task<IResult> Transfer(TransferRequest request, V3Db04Db db)
    {
        if (request.Amount <= 0)
        {
            return TypedResults.BadRequest("amount must be positive.");
        }

        // A self-transfer would load one entity, debit and credit the same
        // object and net to zero. Correct, and certainly not what was meant.
        if (request.FromId == request.ToId)
        {
            return TypedResults.BadRequest("from and to must differ.");
        }

        var pair = await db.Accounts
            .Where(a => a.Id == request.FromId || a.Id == request.ToId)
            .ToListAsync();

        var from = pair.SingleOrDefault(a => a.Id == request.FromId);
        var to = pair.SingleOrDefault(a => a.Id == request.ToId);
        if (from is null || to is null)
        {
            return TypedResults.NotFound();
        }

        if (from.Balance < request.Amount)
        {
            return TypedResults.BadRequest("insufficient funds.");
        }

        from.Balance -= request.Amount;
        to.Balance += request.Amount;

        // One SaveChanges, one transaction, both UPDATEs or neither. No
        // BeginTransaction needed - the extra save was the bug.
        await db.SaveChangesAsync();

        return TypedResults.Ok(new TransferResult(from.Balance, to.Balance));
    }
}

