using Microsoft.EntityFrameworkCore;

namespace DotnetDojo.Api.V3DB04_TransactionsConcurrency;

public class Ex3 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapPut("/v3db04/accounts/{id:int}/limit", SetLimit);
    }

    private static async Task<IResult> SetLimit(int id, LimitRequest request, V3Db04Db db)
    {
        var account = await db.Accounts.FirstOrDefaultAsync(a => a.Id == id);
        if (account is null)
        {
            return TypedResults.NotFound();
        }

        // Without this, EF compares against the version it read milliseconds
        // ago, which is true almost always and answers the wrong question.
        // The version that matters is the one the client was looking at.
        db.Entry(account).Property(a => a.RowVersion).OriginalValue =
            Convert.FromBase64String(request.ExpectedVersion);

        account.Limit = request.Limit;

        try
        {
            await db.SaveChangesAsync();
        }
        catch (DbUpdateConcurrencyException)
        {
            // The entity in hand is stale; report what the database holds so
            // the client can show the user what actually changed.
            var current = await db.Accounts.AsNoTracking().FirstAsync(a => a.Id == id);
            return TypedResults.Json(
                new
                {
                    currentLimit = current.Limit,
                    currentVersion = Convert.ToBase64String(current.RowVersion),
                },
                statusCode: StatusCodes.Status409Conflict);
        }

        return TypedResults.Ok(new
        {
            limit = account.Limit,
            version = Convert.ToBase64String(account.RowVersion),
        });
    }
}

