using Microsoft.EntityFrameworkCore;

namespace DotnetDojo.Api.V3DB04_TransactionsConcurrency;

public class Ex4 : IEndpointMapper
{
    private const int MaxAttempts = 3;

    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapPost("/v3db04/accounts/{id:int}/note", AddNote);
    }

    private static async Task<IResult> AddNote(int id, NoteRequest request, V3Db04Db db)
    {
        var account = await db.Accounts.FirstOrDefaultAsync(a => a.Id == id);
        if (account is null)
        {
            return TypedResults.NotFound();
        }

        Append(account, request.Text);

        for (int retries = 0; retries < MaxAttempts; retries++)
        {
            try
            {
                await db.SaveChangesAsync();
                return TypedResults.Ok(new NoteResult(account.Notes, account.ReviewCount, retries));
            }
            catch (DbUpdateConcurrencyException ex)
            {
                var entry = ex.Entries.Single();
                var store = await entry.GetDatabaseValues();
                if (store is null)
                {
                    // Deleted by the other writer: there is nothing to merge into.
                    return TypedResults.NotFound();
                }

                var fresh = (Account)store.ToObject();

                // Store wins: the count is a fact about the world, so start
                // from the database's value and add our one review.
                account.ReviewCount = fresh.ReviewCount + 1;

                // Client wins: our line is ours, appended to whatever the
                // database now holds.
                account.Notes = Combine(fresh.Notes, request.Text);

                // Without this the next save carries the stale version and
                // conflicts again forever.
                entry.OriginalValues.SetValues(store);
            }
        }

        return TypedResults.Json(
            new { error = "could not merge" },
            statusCode: StatusCodes.Status409Conflict);
    }

    private static void Append(Account account, string text)
    {
        account.Notes = Combine(account.Notes, text);
        account.ReviewCount += 1;
    }

    private static string Combine(string? existing, string text) =>
        string.IsNullOrEmpty(existing) ? text : existing + "\n" + text;
}

exercises.hints:
## Hint 1

Read the exception message; it tells you the API. Then ask *why* the framework
refuses. The strategy retries one execution at a time — and retrying one
command inside a transaction that the server may already have aborted would
apply half a unit of work.

## Hint 2

```csharp
var strategy = db.Database.CreateExecutionStrategy();
await strategy.ExecuteAsync(async () =>
{
    await using var tx = await db.Database.BeginTransactionAsync();
    // …
    await tx.CommitAsync();
});
```

The lambda is now the retry unit, which is the only granularity that can be
correct.

## Hint 3

Everything inside the lambda runs again on a retry, so read the accounts
*inside* it, not outside. Your `attempts` counter has to live outside and be
incremented at the top of the lambda — think about what else in your handler
must be reset rather than accumulated.

