// v3db04_transactions_concurrency / ex5 - reference solution (author only, used by `dojo verify`).

using Microsoft.EntityFrameworkCore;

namespace DotnetDojo.Api.V3DB04_TransactionsConcurrency;

public class Ex5 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapPost("/v3db04/batch-adjust", BatchAdjust);
    }

    private static async Task<IResult> BatchAdjust(AdjustRequest request, Ex5Db db)
    {
        int attempts = 0;
        IResult? failure = null;
        int applied = 0;

        // The whole unit of work is the retry unit. Retrying a single command
        // inside an open transaction could apply half of it.
        var strategy = db.Database.CreateExecutionStrategy();
        await strategy.ExecuteAsync(async () =>
        {
            attempts++;
            failure = null;
            applied = 0;

            await using var tx = await db.Database.BeginTransactionAsync();

            // Read inside the lambda: anything read outside is stale on the
            // second attempt.
            var ids = request.Adjustments.Select(a => a.AccountId).Distinct().ToList();
            var accounts = await db.Accounts
                .Where(a => ids.Contains(a.Id))
                .ToDictionaryAsync(a => a.Id);

            // Deterministic order: two overlapping batches applied in
            // different orders is the textbook deadlock cycle.
            foreach (var adjustment in request.Adjustments.OrderBy(a => a.AccountId))
            {
                if (!accounts.TryGetValue(adjustment.AccountId, out var account))
                {
                    failure = TypedResults.NotFound(new { unknownAccountId = adjustment.AccountId });
                    return;
                }

                if (account.Balance + adjustment.Delta < 0)
                {
                    failure = TypedResults.BadRequest(
                        new { error = $"account {account.Id} would go negative." });
                    return;
                }

                account.Balance += adjustment.Delta;
                applied++;
            }

            await db.SaveChangesAsync();
            await tx.CommitAsync();
        });

        return failure ?? TypedResults.Ok(new { applied, attempts });
    }
}

