namespace DotnetDojo.Api.V3DB04_TransactionsConcurrency;

public class Ex6 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapPost("/v3db04/seats/{id:int}/hold", Hold);
    }

    private static async Task<IResult> Hold(int id, HoldRequest request, V3Db04Db db)
    {
        // Check and write in one statement: the row lock arbitrates, so
        // exactly one of twenty concurrent callers gets a 1 back.
        int claimed = await db.Seats
            .Where(s => s.Id == id && s.HolderId == null)
            .ExecuteUpdateAsync(s => s.SetProperty(x => x.HolderId, request.HolderId));

        if (claimed == 1)
        {
            return TypedResults.Ok(new { held = true });
        }

        // Only the losing path pays for a second round trip, and only there is
        // it needed: 0 means "taken" or "absent", and those differ.
        var current = await db.Seats
            .AsNoTracking()
            .Where(s => s.Id == id)
            .Select(s => new { s.HolderId })
            .FirstOrDefaultAsync();

        if (current is null)
        {
            return TypedResults.NotFound();
        }

        return TypedResults.Json(
            new { held = false, holderId = current.HolderId },
            statusCode: StatusCodes.Status409Conflict);
    }
}

