using Microsoft.EntityFrameworkCore;

namespace DotnetDojo.Api.V3DB04_TransactionsConcurrency;

public class Ex7 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapPost("/v3db04/payments", Pay);
    }

    private static async Task<IResult> Pay(HttpRequest http, PaymentRequest request, V3Db04Db db)
    {
        string? key = http.Headers["Idempotency-Key"].FirstOrDefault();
        if (string.IsNullOrWhiteSpace(key))
        {
            return TypedResults.BadRequest("Idempotency-Key header is required.");
        }

        string hash = V3Db04Hash.Of(request);

        var existing = await db.IdempotencyRecords.AsNoTracking()
            .FirstOrDefaultAsync(r => r.Key == key);
        if (existing is not null)
        {
            return Replay(existing, hash);
        }

        var payment = new Payment
        {
            AccountId = request.AccountId,
            Amount = request.Amount,
            Description = request.Description,
        };
        db.Payments.Add(payment);

        // Same transaction as the payment: a record without a payment replays
        // something that never happened, and a payment without a record is
        // charged twice on retry.
        var record = new IdempotencyRecord { Key = key, RequestHash = hash };
        db.IdempotencyRecords.Add(record);

        try
        {
            await db.SaveChangesAsync();
            record.ResponseBody = V3Db04Hash.Serialise(new { paymentId = payment.Id, replayed = true });
            await db.SaveChangesAsync();
        }
        catch (DbUpdateException ex) when (V3Db04Db.IsUniqueViolation(ex))
        {
            // A concurrent request recorded this key between our lookup and
            // our insert. That is not an error; it is a replay.
            var winner = await db.IdempotencyRecords.AsNoTracking()
                .FirstAsync(r => r.Key == key);
            return Replay(winner, hash);
        }

        return TypedResults.Created(
            $"/v3db04/payments/{payment.Id}",
            new { paymentId = payment.Id, replayed = false });
    }

    private static IResult Replay(IdempotencyRecord record, string hash)
    {
        if (record.RequestHash != hash)
        {
            return TypedResults.UnprocessableEntity(
                new { error = "idempotency key reused with a different payload" });
        }

        return TypedResults.Text(
            record.ResponseBody ?? "{}",
            contentType: "application/json",
            statusCode: StatusCodes.Status200OK);
    }
}

