namespace DotnetDojo.Api.V3DB04_TransactionsConcurrency;

public class Ex8 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapPost("/v3db04/transfers/locked", LockedTransfer);
    }

    private static async Task<IResult> LockedTransfer(TransferRequest request, V3Db04Db db)
    {
        if (request.Amount <= 0 || request.FromId == request.ToId)
        {
            return TypedResults.BadRequest("amount must be positive and accounts must differ.");
        }

        await using var tx = await db.Database.BeginTransactionAsync();

        // Ascending id, always - whatever direction the money is going. A
        // cycle needs two transactions acquiring in opposite orders, so a
        // single global order makes deadlock impossible rather than unlikely.
        var locked = new Dictionary<int, Account>();
        foreach (int id in new[] { request.FromId, request.ToId }.Order())
        {
            var account = await V3Db04Lock.SelectForUpdateAsync(db, id);
            if (account is null)
            {
                return TypedResults.NotFound();
            }
            locked[id] = account;
        }

        var from = locked[request.FromId];
        var to = locked[request.ToId];

        if (from.Balance < request.Amount)
        {
            return TypedResults.BadRequest("insufficient funds.");
        }

        // Both rows are held, so the direction of the transfer is independent
        // of the order they were locked in.
        from.Balance -= request.Amount;
        to.Balance += request.Amount;

        await db.SaveChangesAsync();
        await tx.CommitAsync();

        return TypedResults.Ok(new TransferResult(from.Balance, to.Balance));
    }
}

