        if (string.IsNullOrWhiteSpace(key))
        {
            return TypedResults.BadRequest(new { error = "Idempotency-Key header is required." });
        }
        if (request.Price <= 0)
        {
            return TypedResults.BadRequest(new { error = "price must be positive." });
        }

        string hash = V3Db04Hash.Of(request);
        IResult? outcome = null;
        int attempts = 0;

        var strategy = db.Database.CreateExecutionStrategy();
        await strategy.ExecuteAsync(async () =>
        {
            attempts++;
            outcome = null;
            db.ChangeTracker.Clear();

            await using var tx = await db.Database.BeginTransactionAsync();

            // Inside the lambda: on a retry after an ambiguous commit, the
            // first attempt's record may now exist, and this is how we find out.
            var record = await db.IdempotencyRecords.AsNoTracking()
                .FirstOrDefaultAsync(r => r.Key == key);
            if (record is not null)
            {
                outcome = record.RequestHash != hash
                    ? TypedResults.UnprocessableEntity(
                        new { error = "idempotency key reused with a different payload" })
                    : TypedResults.Text(record.ResponseBody ?? "{}", "application/json", statusCode: 200);
                return;
