            int held = await db.Seats
                .Where(s => s.Id == request.SeatId && s.HolderId == null)
                .ExecuteUpdateAsync(s => s.SetProperty(x => x.HolderId, request.AccountId));
            if (held == 0)
            {
                outcome = TypedResults.Json(new { error = "seat taken" }, statusCode: 409);
                return;
            }

            if (account.Balance < request.Price)
            {
                outcome = TypedResults.Json(
                    new { error = "insufficient funds" },
                    statusCode: StatusCodes.Status402PaymentRequired);
                return;
            }

            account.Balance -= request.Price;

            var booking = new Booking
            {
                SeatId = request.SeatId,
                AccountId = request.AccountId,
                Price = request.Price,
            };
            db.Bookings.Add(booking);
            await db.SaveChangesAsync();

            // Same transaction as the booking. A record without a booking
            // replays something that never happened; a booking without a
            // record is created twice on retry.
            db.IdempotencyRecords.Add(new IdempotencyRecord
            {
                Key = key,
                RequestHash = hash,
                ResponseBody = V3Db04Hash.Serialise(new { bookingId = booking.Id, replayed = true }),
