            await db.SaveChangesAsync();
            await tx.CommitAsync();

            outcome = TypedResults.Created(
                $"/v3db04/bookings/{booking.Id}",
                new { bookingId = booking.Id, replayed = false, attempts });
        });

        return outcome!;
    }
