        await using var tx = await db.Database.BeginTransactionAsync(level.Value);

        // AsNoTracking on both reads: otherwise the second one is answered
        // from the identity map and measures nothing.
        decimal first = await db.Accounts.AsNoTracking()
            .Where(a => a.Id == accountId).Select(a => a.Balance).FirstAsync();

        // A genuinely separate connection, so this is a second transaction
        // rather than our own uncommitted work.
        await V3Db04Chaos.CommitOtherWriter(scopes, accountId, 25m);

        decimal second = await db.Accounts.AsNoTracking()
            .Where(a => a.Id == accountId).Select(a => a.Balance).FirstAsync();

        await tx.CreateSavepointAsync("notes");
        db.AuditNotes.Add(new AuditNote { AccountId = accountId, Text = "discarded" });
        await db.SaveChangesAsync();
        await tx.RollbackToSavepointAsync("notes");

        db.AuditNotes.Add(new AuditNote { AccountId = accountId, Text = "kept" });
        await db.SaveChangesAsync();
        await tx.CommitAsync();

        int committed = await db.AuditNotes.CountAsync(n => n.AccountId == accountId);

        return TypedResults.Ok(new
        {
            first,
            second,
            repeatable = first == second,
            notesCommitted = committed,
