namespace DotnetDojo.Api.V3DB05_BackgroundWork;

public sealed class Ex4Worker(ILogger<Ex4Worker> logger) : BackgroundService
{
    public int Processed;
    public int Failures;

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        await Task.Yield();

        int consecutive = 0;
        while (!stoppingToken.IsCancellationRequested)
        {
            try
            {
                string item = V3Db05Work.NextFlaky();
                V3Db05Log.Append(item);
                Interlocked.Increment(ref Processed);
                consecutive = 0;
            }
            catch (OperationCanceledException) when (stoppingToken.IsCancellationRequested)
            {
                break;
            }
            catch (Exception ex)
            {
                // Expected failure from a known-flaky dependency: contain it
                // here rather than letting it end the service - and therefore,
                // by default, the host.
                Interlocked.Increment(ref Failures);
                consecutive++;
                logger.LogWarning(ex, "flaky iteration failed ({Consecutive} in a row)", consecutive);
            }

            // Backoff on repeated failure: a tight retry loop turns one
            // unhappy dependency into two outages.
            int wait = consecutive > 3 ? 100 : 30;
            try
            {
                await Task.Delay(TimeSpan.FromMilliseconds(wait), stoppingToken);
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }
}

