public sealed class Ex5Worker : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        await Task.Yield();

        // Ticks on a schedule: the body's duration comes out of the gap
        // instead of adding to it. Returns false on cancellation, so the loop
        // needs no shutdown try/catch.
        using var timer = new PeriodicTimer(TimeSpan.FromMilliseconds(100));
        while (await timer.WaitForNextTickAsync(stoppingToken))
        {
            await V3Db05Work.VariableAsync();
        }
    }
}

public class Ex5 : IEndpointMapper, IServiceRegistrar
{
    public void Register(IServiceCollection services, IConfiguration configuration)
    {
        services.AddHostedService<Ex5Worker>();
    }

    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapGet("/v3db05/drift", Drift);
    }

    private static IResult Drift()
    {
        var ticks = V3Db05Work.Ticks;
        if (ticks.Count < 2)
        {
            return TypedResults.Ok(new { ticks = ticks.Count, maxGapMs = 0, cumulativeDriftMs = 0 });
        }

        double maxGap = 0;
        for (int i = 1; i < ticks.Count; i++)
        {
            maxGap = Math.Max(maxGap, (ticks[i] - ticks[i - 1]).TotalMilliseconds);
        }

        double span = (ticks[^1] - ticks[0]).TotalMilliseconds;
        double drift = span - ((ticks.Count - 1) * 100.0);

        return TypedResults.Ok(new
        {
            ticks = ticks.Count,
            maxGapMs = (int)Math.Round(maxGap),
            cumulativeDriftMs = (int)Math.Round(Math.Abs(drift)),
        });
    }
}

