        // unstarted work this service is willing to owe.
        services.AddSingleton(Channel.CreateBounded<PickJob>(new BoundedChannelOptions(8)
        {
            FullMode = BoundedChannelFullMode.Wait,
            SingleReader = true,
        }));
        services.AddSingleton<Ex6Counters>();
        services.AddHostedService<Ex6Worker>();
