public sealed class OutboxPublisher(IServiceScopeFactory scopes, string workerId) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        await Task.Yield();

        while (!stoppingToken.IsCancellationRequested)
        {
            try
            {
                using var scope = scopes.CreateScope();
                var db = scope.ServiceProvider.GetRequiredService<V3Db05Db>();

                var rows = await V3Db05Sql.ClaimOutbox(db, workerId, 5);
                if (rows.Count == 0)
                {
                    await Task.Delay(TimeSpan.FromMilliseconds(25), stoppingToken);
                    continue;
                }

                foreach (var row in rows)
                {
                    try
                    {
                        // Send first, then mark. The other order can lose a
                        // message; this one can only duplicate it, and the
                        // stable MessageId lets the consumer discard the copy.
                        await V3Db05Bus.PublishAsync(row.MessageId, row.Payload, stoppingToken);
                        row.PublishedAt = DateTime.UtcNow;
                    }
                    catch (Exception)
                    {
                        // Leave it claimable: released, not published.
                        row.ClaimedBy = null;
                    }
                }

                await db.SaveChangesAsync(stoppingToken);
            }
            catch (OperationCanceledException) when (stoppingToken.IsCancellationRequested)
            {
                break;
            }
        }
    }
}

