    {
        app.MapPost("/v3db05/orders", Create);
        app.MapGet("/v3db05/outbox", Report);
    }

    private static async Task<IResult> Create(OrderRequest request, V3Db05Db db)
    {
        if (string.IsNullOrWhiteSpace(request.Reference))
        {
            return TypedResults.BadRequest("reference is required.");
        }

        // One commit covers the business data and the message, which is the
        // entire point: two systems, one atomic decision.
        await using var tx = await db.Database.BeginTransactionAsync();

        var order = new Order { Reference = request.Reference, Status = "new" };
        db.Orders.Add(order);
        await db.SaveChangesAsync();

        db.Outbox.Add(new Outbox
        {
            MessageId = Guid.NewGuid(),
            Payload = V3Db05Bus.Describe(order),
        });
        await db.SaveChangesAsync();
        await tx.CommitAsync();

        return TypedResults.Created($"/v3db05/orders/{order.Id}", new { orderId = order.Id });
    }

