    {
        int written = await db.Outbox.CountAsync();
        int published = await db.Outbox.CountAsync(o => o.PublishedAt != null);

        return TypedResults.Ok(new
        {
            written,
            published,
            delivered = V3Db05Bus.Stats.Delivered,
            duplicatesDelivered = V3Db05Bus.Stats.Duplicates,
        });
    }
