namespace DotnetDojo.Api.V3DB05_BackgroundWork;

public class Review1 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapGet("/v3db05/wait", Wait);
        app.MapGet("/v3db05/wait/stats", Stats);
    }

    private static async Task<IResult> Wait(int ms, HttpContext http)
    {
        if (ms < 1 || ms > 5000)
        {
            return TypedResults.BadRequest("ms must be between 1 and 5000.");
        }

        using var timeout = new CancellationTokenSource(TimeSpan.FromMilliseconds(ms));

        // One token, three reasons. The linked token cannot say which fired,
        // which is why the sources are kept.
        using var linked = CancellationTokenSource.CreateLinkedTokenSource(
            timeout.Token, http.RequestAborted);

        var idle = Task.Delay(Timeout.Infinite, linked.Token);
        var finished = await Task.WhenAny(V3Db05Work.Signal.Task, idle);

        if (finished == V3Db05Work.Signal.Task)
        {
            V3Db05Work.CountSignalled();
            return TypedResults.Ok(new { reason = "signalled" });
        }

        // Observe the cancelled delay so it is not an unobserved exception.
        _ = idle.Exception;

        // Abort first: if the client has gone, there is nobody to hand a
        // timeout to, whichever token technically fired.
        if (http.RequestAborted.IsCancellationRequested)
        {
            V3Db05Work.CountAborted();
            return TypedResults.StatusCode(499);
        }

        V3Db05Work.CountTimedOut();
        return TypedResults.Ok(new { reason = "timeout" });
    }

    private static IResult Stats() =>
        TypedResults.Ok(new
        {
            signalled = V3Db05Work.Signalled,
            timedOut = V3Db05Work.TimedOut,
            aborted = V3Db05Work.Aborted,
        });
}

