    {
        var root = (IConfigurationRoot)configuration;

        // TryGet, not configuration[key]: an empty string is a value, and
        // indexing conflates it with "nobody has this key".
        string? value = null;
        bool found = false;
        foreach (var provider in root.Providers)
        {
            if (provider.TryGet(key, out var candidate))
            {
                value = candidate;
                found = true;
            }
