using Microsoft.Extensions.Primitives;

namespace DotnetDojo.Api.V3DB06_ConfigSecrets;

public sealed class Ex2Reloader : IDisposable
{
    private readonly IConfiguration _configuration;
    private readonly ILogger<Ex2Reloader> _logger;
    private readonly IDisposable? _registration;
    private CancellationTokenSource? _pending;

    public int Changes;
    public int Rebuilds;
    public string? LastValue;

    public Ex2Reloader(IConfiguration configuration, ILogger<Ex2Reloader> logger)
    {
        _configuration = configuration;
        _logger = logger;

        // The lambda must hand back a NEW token each time it is called;
        // returning a cached one makes the callback fire exactly once, ever.
        _registration = ChangeToken.OnChange(
            () => configuration.GetReloadToken(),
            OnChanged);
    }

    private void OnChanged()
    {
        Interlocked.Increment(ref Changes);

        _pending?.Cancel();
        var cts = _pending = new CancellationTokenSource();

        _ = Task.Run(async () =>
        {
            try
            {
                // Coalesce the pair of events a single save produces.
                await Task.Delay(TimeSpan.FromMilliseconds(250), cts.Token);
            }
            catch (OperationCanceledException)
            {
                return;
            }

            try
            {
                // Read AFTER the window: the first event can arrive while the
                // source is half written.
                string? value = _configuration["Dojo:Reload:Value"];
                await V3Db06Cache.RebuildAsync(value);
                LastValue = value;
                Interlocked.Increment(ref Rebuilds);
            }
            catch (Exception ex)
            {
                // A failed reload must never be worse than no reload.
                _logger.LogError(ex, "configuration reload failed; keeping previous cache");
            }
        });
    }

    public void Dispose() => _registration?.Dispose();
}

public class Ex2 : IEndpointMapper, IServiceRegistrar
{
    public void Register(IServiceCollection services, IConfiguration configuration)
    {
        services.AddSingleton<Ex2Reloader>();
        services.AddHostedService(sp =>
            new V3Db06Activator(() => sp.GetRequiredService<Ex2Reloader>()));
    }

    public void MapEndpoints(IEndpointRouteBuilder app)
    {
