// v3db06_config_secrets / ex4 - reference solution (author only, used by `dojo verify`).

using Microsoft.Extensions.Options;

namespace DotnetDojo.Api.V3DB06_ConfigSecrets;

public sealed class MailerValidator : IValidateOptions<MailerOptions>
{
    public ValidateOptionsResult Validate(string? name, MailerOptions options)
    {
        // Collect, never short-circuit: one error per restart is a miserable
        // loop for whoever is fixing the file.
        var failures = new List<string>();

        if (string.IsNullOrWhiteSpace(options.Host))
        {
            failures.Add("Host must not be blank.");
        }
        if (options.Port is < 1 or > 65535)
        {
            failures.Add($"Port {options.Port} is out of range.");
        }
        if (options.FromAddress is null || !options.FromAddress.Contains('@'))
        {
            failures.Add("FromAddress must contain '@'.");
        }
        if (options.RetryCount is < 0 or > 10)
        {
            failures.Add("RetryCount must be between 0 and 10.");
        }

        return failures.Count == 0
            ? ValidateOptionsResult.Success
            : ValidateOptionsResult.Fail(failures);
    }
}

