        services.AddOptions<MailerOptions>()
            .Bind(configuration.GetSection("Dojo:Mailer"))
            .ValidateDataAnnotations()
            // Separate opt-in, and the one that matters: without it the
            // failure surfaces on an unlucky request instead of at deploy.
            .ValidateOnStart();
