    private static IResult Validate(
        string? host,
        int port,
        string? from,
        int retry,
        IValidateOptions<MailerOptions> validator)
    {
        var candidate = new MailerOptions
        {
            Host = host ?? string.Empty,
            Port = port,
            FromAddress = from ?? string.Empty,
            RetryCount = retry,
        };

        var result = validator.Validate(null, candidate);

        return TypedResults.Ok(new
        {
            valid = result.Succeeded,
            failures = result.Failures?.ToList() ?? [],
        });
    }
}

