using Microsoft.Extensions.Options;

namespace DotnetDojo.Api.V3DB06_ConfigSecrets;

public class Ex5 : IEndpointMapper, IServiceRegistrar
{
    public void Register(IServiceCollection services, IConfiguration configuration)
    {
        string environment =
            configuration["ASPNETCORE_ENVIRONMENT"] ?? "Development";

        services.AddOptions<ClientOptions>()
            // Phase 1. Configure and Bind are the same phase, run in
            // registration order - so the default must come first or
            // configuration is silently overwritten.
            .Configure(o =>
            {
                V3Db06Trace.Note("library-default");
                o.Timeout = TimeSpan.FromSeconds(30);
                o.UserAgent = "dojo";
            })
            .Configure(o => V3Db06Trace.Note("configuration"))
            .Bind(configuration.GetSection("Dojo:Client"))
            // Phase 2, always after every configure step: a transformation of
            // whatever the result turned out to be, not a default.
            .PostConfigure(o =>
            {
                V3Db06Trace.Note("post-configure");
                o.UserAgent = $"{o.UserAgent} ({environment})";
                if (o.BaseUrl.StartsWith("http://", StringComparison.OrdinalIgnoreCase))
                {
                    o.BaseUrl = string.Concat("https://", o.BaseUrl.AsSpan("http://".Length));
                }
            });
    }

    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapGet("/v3db06/client", (IOptions<ClientOptions> options) =>
        {
            var value = options.Value;
            return TypedResults.Ok(new
            {
                timeout = value.Timeout.ToString(),
                userAgent = value.UserAgent,
                baseUrl = value.BaseUrl,
                order = V3Db06Trace.Order,
            });
        });
    }
}

