using Microsoft.Extensions.Configuration;

namespace DotnetDojo.Api.V3DB06_ConfigSecrets;

public class Ex6 : IEndpointMapper, IServiceRegistrar
{
    public void Register(IServiceCollection services, IConfiguration configuration)
    {
        // Rule relied on: init-only properties and positional records bind
        // when the BINDER constructs the object. Get<T>() and Bind(section,
        // instance) differ exactly there - the second cannot use init setters
        // or a constructor, because the instance already exists.
        services.AddOptions<IngestOptions>()
            .Configure<IConfiguration>((options, config) => { })
            .Bind(configuration.GetSection("Dojo:Ingest"));
    }

    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapGet("/v3db06/ingest", Ingest);
        app.MapGet("/v3db06/ingest/strict", Strict);
    }

    private static IResult Ingest(IConfiguration configuration)
    {
        // Get<T> constructs, so the init-only Window and the positional Retry
        // record both bind.
        var options = configuration.GetSection("Dojo:Ingest").Get<IngestOptions>()!;

        return TypedResults.Ok(new
        {
            endpoints = options.Endpoints,
            limits = options.Limits,
            window = options.Window.ToString(),
            mode = options.Mode.ToString(),
            retry = new
            {
                attempts = options.Retry.Attempts,
                backoff = options.Retry.Backoff.ToString(),
            },
        });
    }

    private static IResult Strict(IConfiguration configuration)
    {
        try
        {
            // A typo'd key is silent by default: the property keeps its value
            // and the service is subtly wrong. This turns it into an error.
            _ = configuration.GetSection("Dojo:Ingest")
                .Get<IngestOptions>(binder => binder.ErrorOnUnknownConfiguration = true);

            return TypedResults.Ok(new { bound = true });
        }
        catch (InvalidOperationException ex)
        {
            return TypedResults.Ok(new { bound = false, error = ex.Message });
        }
    }
}

exercises.hints:
## Hint 1

`ConfigurationRoot["a:b"]` iterates `Providers` **in reverse** and returns the
first hit. So the winner is the last provider in the list that has the key,
and building the candidate list in forward order gives you the override
history for free.

## Hint 2

```csharp
var root = (IConfigurationRoot)configuration;
foreach (var provider in root.Providers)
{
    if (provider.TryGet(key, out var value))
    {
        candidates.Add($"{provider.GetType().Name}={value}");
    }
}
```

The last entry is the effective one.

## Hint 3

Watch the environment-variable spelling. `Dojo__Gate__Limit` is stored by the
provider as `Dojo:Gate:Limit` — the translation happens on load, not on read —
so `TryGet` takes the colon form and the double underscore never appears in
your code. Confirm that rather than assuming it.

