// v3db06_config_secrets / ex7 - reference solution (author only, used by `dojo verify`).

namespace DotnetDojo.Api.V3DB06_ConfigSecrets;

public class Ex7 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapGet("/v3db06/whence", Whence);
    }

    private static IResult Whence(string key, IConfiguration configuration)
    {
        var root = (IConfigurationRoot)configuration;

        // Forward order, so the list reads as the override history. Reading a
        // value walks this same list backwards, which is why the last entry
        // is the effective one.
        var candidates = new List<string>();
        string? winningProvider = null;
        string? winningValue = null;

        foreach (var provider in root.Providers)
        {
            // Environment variables are stored with the colon form: the
            // Dojo__Gate__Limit spelling is translated on load, not on read.
            if (provider.TryGet(key, out var value))
            {
                candidates.Add($"{provider.GetType().Name}={value}");
                winningProvider = provider.GetType().Name;
                winningValue = value;
            }
        }

        if (winningProvider is null)
        {
            return TypedResults.NotFound();
        }

        return TypedResults.Ok(new
        {
            key,
            value = winningValue,
            provider = winningProvider,
            candidates,
        });
    }
}

