// v3db06_config_secrets / ex8 - reference solution (author only, used by `dojo verify`).

namespace DotnetDojo.Api.V3DB06_ConfigSecrets;

public class Ex8 : IEndpointMapper
{
    private static readonly string[] SensitiveSegments =
        ["password", "secret", "token", "key", "connectionstring"];

    private static readonly string[] SensitiveValueMarkers = ["password=", "pwd="];

    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapGet("/v3db06/dump", Dump);
    }

    private static IResult Dump(IConfiguration configuration)
    {
        int redacted = 0;
        var entries = new List<object>();

        foreach (var pair in configuration.AsEnumerable()
                     .Where(p => p.Value is not null)
                     .OrderBy(p => p.Key, StringComparer.Ordinal))
        {
            if (IsSensitive(pair.Key, pair.Value!))
            {
                redacted++;
                entries.Add(new { key = pair.Key, value = "***" });
            }
            else
            {
                entries.Add(new { key = pair.Key, value = pair.Value });
            }
        }

        return TypedResults.Ok(new { redacted, entries });
    }

    private static bool IsSensitive(string key, string value)
    {
        // Key rule: the last segment only. Matching the whole path would
        // redact Dojo:Keyboard:Layout, and over-redaction is how people end up
        // turning redaction off.
        string last = key.Split(':')[^1];
        if (SensitiveSegments.Any(s => last.Contains(s, StringComparison.OrdinalIgnoreCase)))
        {
            return true;
        }

        // Value rule: catches the connection string filed under an innocuous
        // name, which no key rule would ever flag.
        return SensitiveValueMarkers.Any(m => value.Contains(m, StringComparison.OrdinalIgnoreCase));
    }
}

