// v3db06_config_secrets / challenge - reference solution (author only, used by `dojo verify`).

using Microsoft.Extensions.Options;

namespace DotnetDojo.Api.V3DB06_ConfigSecrets;

public sealed class FlagValidator : IValidateOptions<FlagOptions>
{
    public ValidateOptionsResult Validate(string? name, FlagOptions options)
    {
        var failures = new List<string>();

        foreach (var (flag, definition) in options.Flags)
        {
            if (definition.Percentage is < 0 or > 100)
            {
                failures.Add($"Flag '{flag}': percentage {definition.Percentage} must be 0-100.");
            }
            if (definition.Environments.Count == 0)
            {
                failures.Add($"Flag '{flag}': at least one environment is required.");
            }
        }

        return failures.Count == 0
            ? ValidateOptionsResult.Success
            : ValidateOptionsResult.Fail(failures);
    }
}

public class Challenge : IEndpointMapper, IServiceRegistrar
{
    public void Register(IServiceCollection services, IConfiguration configuration)
    {
        services.AddSingleton<IValidateOptions<FlagOptions>, FlagValidator>();

        services.AddOptions<FlagOptions>()
            .Bind(configuration.GetSection("Dojo:Flags"))
            .ValidateOnStart();
    }

    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapGet("/v3db06/flags/{name}", Evaluate);
    }

    private static IResult Evaluate(
        string name,
        string? user,
        // Monitor, not IOptions: IOptions is computed once for the process and
        // would freeze every flag at boot.
        IOptionsMonitor<FlagOptions> flags,
        IHostEnvironment environment)
    {
        if (string.IsNullOrWhiteSpace(user))
        {
            return TypedResults.BadRequest(new { error = "user is required." });
        }

        if (!flags.CurrentValue.Flags.TryGetValue(name, out var definition))
        {
            return TypedResults.NotFound();
        }

        // Order matters and is not interchangeable: environment gate, then
        // kill switch, then shortcut, then rollout.
        if (!definition.Environments.Contains(environment.EnvironmentName, StringComparer.OrdinalIgnoreCase))
        {
            return TypedResults.Ok(new { name, on = false, reason = "environment" });
        }

        if (!definition.Enabled)
        {
            return TypedResults.Ok(new { name, on = false, reason = "disabled" });
        }

        if (definition.Percentage >= 100)
        {
            return TypedResults.Ok(new { name, on = true, reason = "enabled" });
        }

        // Hashed, not random: a user who flickers between variants on every
        // page load is worse off than under either variant.
        bool on = V3Db06Hash.Bucket(name, user) < definition.Percentage;
        return TypedResults.Ok(new { name, on, reason = "percentage" });
    }
}

