using Microsoft.Extensions.Options;

namespace DotnetDojo.Api.V3DB06_ConfigSecrets;

public class Review1 : IEndpointMapper, IServiceRegistrar
{
    public void Register(IServiceCollection services, IConfiguration configuration)
    {
        // The only place in this file that knows what an environment is.
        string environment = configuration["ASPNETCORE_ENVIRONMENT"] ?? "Production";

        if (environment is "Development" or "Staging")
        {
            services.AddSingleton<IReceiptSender, RecordingSender>();
        }
        else
        {
            // Registered only on this branch: a developer with no SMTP
            // endpoint can still start the app, and production cannot.
            services.AddOptions<ReceiptOptions>()
                .Bind(configuration.GetSection("Dojo:Receipts"))
                .Validate(o => !string.IsNullOrWhiteSpace(o.Endpoint),
                    "Dojo:Receipts:Endpoint is required in Production.")
                .ValidateOnStart();

            services.AddSingleton<IReceiptSender, SmtpSender>();
        }

        services.AddSingleton(new SenderDescription(
            environment,
            environment is "Development" or "Staging"
                ? nameof(RecordingSender)
                : nameof(SmtpSender)));
    }

    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapGet("/v3db06/sender", Describe);
        app.MapPost("/v3db06/receipts", Send);
    }

    private static IResult Describe(SenderDescription description) =>
        TypedResults.Ok(new
        {
            environment = description.Environment,
            implementation = description.Implementation,
            decidedIn = "Register",
        });

    private static async Task<IResult> Send(ReceiptRequest request, IReceiptSender sender)
    {
        // Cannot tell which implementation it received, which is the point.
        string id = await sender.SendAsync(request.To, request.Body);
        return TypedResults.Ok(new { transportId = id });
    }
}
